            database = container "Database" "Stores shipments and dispatch records" "Database" "Database"
        }

        emailProvider = softwareSystem "Email Delivery Provider" "An external email delivery provider operated by a different organization" "External"

        customer -> parcelTracker.webPortal "looks up the status of their parcels" "Web browser"
        parcelTracker.webPortal -> parcelTracker.pricingLibrary "embeds" "In-process"
        parcelTracker.dispatchService -> parcelTracker.pricingLibrary "embeds" "In-process"
        parcelTracker.dispatchService -> emailProvider "sends customer notification emails through" "SMTP"
        parcelTracker.webPortal -> parcelTracker.database "reads shipment records from" "SQL"
        parcelTracker.dispatchService -> parcelTracker.database "writes dispatch records to" "SQL"
    }

    views {

        systemContext parcelTracker "SystemContext" {
            include *
            autoLayout
            title "System Context for Parcel Tracker"
        }

        container parcelTracker "Containers" {
            include *
            autoLayout
            title "Containers for Parcel Tracker"
        }

        styles {
            element "Person" {
                shape Person
                background #08427B
                color #ffffff
            }
            element "Software System" {
                background #1168BD
                color #ffffff
            }
            element "External" {
                background #999999
                color #ffffff
            }
            element "Container" {
                background #438DD5
                color #ffffff
            }
            element "Database" {
                shape Cylinder
            }
            element "Software Library" {
                shape Hexagon
            }
        }
    }
}`;

